-- FOODEX Geography Full Reset + 2026-05 Operational Route Sheet
-- =====================================================================
-- PURPOSE
--   Rebuild the canonical Egypt geography hierarchy and make the live
--   service map match "خطوط سير المناديب اسطول فودكس 5/2026".
--
-- RESULT
--   * Egypt root.
--   * 27 governorate geography nodes + governorate service records.
--   * 13 paper-route Service Territories.
--   * 10 primary auto-routing candidates (priority 500).
--   * 3 overlapping operational overlays (Market/Admin/Route 12),
--     routing=false by default.
--   * Each paper route has a real active Polygon/MultiPolygon composed
--     from licensed administrative boundaries; NO point markers.
--
-- GEOMETRY SOURCE / ATTRIBUTION
--   geoBoundaries EGY ADM2, boundary ID EGY-ADM2-37247803, year 2020.
--   Source: OCHA ROMENA/HDX + CAPMAS.
--   License: CC BY 3.0 IGO.
--   Mirrored geometry used by build: robit-man/tiny-atlas, preserving
--   geoBoundaries source metadata and shape IDs.
--
-- NAME/CODE SOURCE
--   Open Admin Data Egypt Administrative Divisions (CC BY 4.0).
--
-- IMPORTANT ROUTING CONTRACT
--   This SQL prepares geography. Issue #1086 owns dispatch behavior:
--   - Only territories with capabilities.routing=true are candidates
--     for no-policy automatic routing.
--   - If more than one PRIMARY route of the same effective priority
--     contains the order coordinate, do NOT pick by code/id. The order
--     must become awaiting_dispatch unless a published Routing Policy
--     explicitly resolves the ambiguity.
--   - Market/Admin/Route 12 remain visible operational overlays but do
--     not participate in no-policy auto-dispatch by default.
--
-- PRIVACY
--   The representative names/mobile numbers shown on the paper are NOT
--   embedded in source-controlled SQL. Existing Users/Vans are assigned
--   to these territory codes through the Dashboard / #1086 workflow.
--
-- RUN THIS WHOLE FILE ONCE.

SET NAMES utf8mb4;
SET @OLD_SQL_SAFE_UPDATES := @@SQL_SAFE_UPDATES;
SET @OLD_FOREIGN_KEY_CHECKS := @@FOREIGN_KEY_CHECKS;
SET SQL_SAFE_UPDATES = 0;

START TRANSACTION;

-- ============================================================
-- 1) FULL RESET OF CANONICAL GEOGRAPHY/TERRITORY DATA
--    Deliberately does NOT delete Vans, Users, Orders or assignment history.
-- ============================================================
SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM address_territory_resolutions;
DELETE FROM territory_geometries;
DELETE FROM service_territories;
DELETE FROM geography_nodes;

SET FOREIGN_KEY_CHECKS = @OLD_FOREIGN_KEY_CHECKS;

-- ============================================================
-- 2) EGYPT ROOT
-- ============================================================
INSERT INTO geography_nodes
(parent_id,type,code,name_ar,name_en,country_code,is_active,metadata,created_at,updated_at)
VALUES
(
 NULL,'country','EG','مصر','Egypt','EG',1,
 JSON_OBJECT(
   'level',0,
   'iso2','EG',
   'timezone','Africa/Cairo',
   'source','FOODEX route-sheet geography bootstrap',
   'route_sheet','2026-05'
 ),
 NOW(),NOW()
);

SET @egypt_id := LAST_INSERT_ID();

