-- ============================================================
-- 5) ALL 27 GOVERNORATES AS HIERARCHY TERRITORIES
--    No active routing geometry is attached here. This prevents an
--    uncovered order from being treated as serviceable merely because
--    it is somewhere inside an Egyptian governorate.
-- ============================================================
INSERT INTO service_territories
(code,name_ar,name_en,country_node_id,governorate_node_id,city_node_id,district_node_id,
 default_warehouse_id,status,priority,effective_from,effective_until,service_calendar,
 tags,capabilities,notes,created_at,updated_at)
SELECT
 CONCAT('EG-GOV-',g.code),
 g.name_ar,
 g.name_en,
 @egypt_id,
 g.id,
 NULL,NULL,NULL,
 'active',
 200,
 NOW(),NULL,NULL,
 JSON_ARRAY('egypt','governorate',g.code),
 JSON_OBJECT(
   'van',TRUE,
   'orders',TRUE,
   'routing',FALSE,
   'hierarchy_only',TRUE
 ),
 'Governorate hierarchy record; paper-route polygons are the operational routing layer.',
 NOW(),NOW()
FROM geography_nodes g
WHERE g.country_code='EG'
  AND g.type='governorate'
  AND g.is_active=1;

