-- ============================================================
-- 8) COMMIT
-- ============================================================
COMMIT;

SET SQL_SAFE_UPDATES = @OLD_SQL_SAFE_UPDATES;
SET FOREIGN_KEY_CHECKS = @OLD_FOREIGN_KEY_CHECKS;

-- ============================================================
-- 9) VERIFICATION
-- Expected:
--   countries               = 1
--   governorates            = 27
--   governorate_territories = 27
--   paper_routes            = 13
--   primary_routing_routes  = 10
--   overlay_routes          = 3
--   route_geometries        = 13
--   missing_route_geometry  = 0
-- ============================================================

SELECT
 SUM(type='country') AS countries,
 SUM(type='governorate') AS governorates
FROM geography_nodes
WHERE country_code='EG';

SELECT COUNT(*) AS governorate_territories
FROM service_territories
WHERE code LIKE 'EG-GOV-%'
  AND status='active';

SELECT
 COUNT(*) AS paper_routes,
 SUM(CASE
       WHEN JSON_UNQUOTE(JSON_EXTRACT(capabilities,'$.routing')) IN ('true','1')
       THEN 1 ELSE 0
     END) AS primary_routing_routes,
 SUM(CASE
       WHEN JSON_UNQUOTE(JSON_EXTRACT(capabilities,'$.routing')) IN ('false','0')
       THEN 1 ELSE 0
     END) AS overlay_routes
FROM service_territories
WHERE code LIKE 'EG-ROUTE-202605-%';

SELECT
 COUNT(*) AS route_geometries
FROM territory_geometries tg
INNER JOIN service_territories st
 ON st.id=tg.service_territory_id
WHERE st.code LIKE 'EG-ROUTE-202605-%'
  AND tg.is_active=1
  AND tg.geometry_type IN ('Polygon','MultiPolygon');

SELECT COUNT(*) AS missing_route_geometry
FROM service_territories st
LEFT JOIN territory_geometries tg
 ON tg.service_territory_id=st.id
AND tg.is_active=1
WHERE st.code LIKE 'EG-ROUTE-202605-%'
  AND tg.id IS NULL;

SELECT
 st.code,
 st.name_ar,
 st.name_en,
 st.priority,
 JSON_UNQUOTE(JSON_EXTRACT(st.capabilities,'$.route_kind')) AS route_kind,
 JSON_UNQUOTE(JSON_EXTRACT(st.capabilities,'$.routing')) AS routing_enabled,
 tg.geometry_type,
 tg.min_lat,
 tg.max_lat,
 tg.min_lng,
 tg.max_lng
FROM service_territories st
INNER JOIN territory_geometries tg
 ON tg.service_territory_id=st.id
WHERE st.code LIKE 'EG-ROUTE-202605-%'
ORDER BY st.priority DESC, st.code;

-- Existing Van assignments are deliberately preserved by this geography reset.
-- After rebuild, use the Dashboard to assign Vans/representatives to the new
-- EG-ROUTE-202605-* territory codes. #1086 must ignore stale territory_key
-- values that no longer resolve to an active Service Territory.
